Change(genesis='e30427e699992327267add669c3bc989f6d16525ba6f493121eec7778638e0ce', deps=('4f7f3403c55500d8d3df819de3ff71ad80b4a4b9bd44417e89e82216d967b290',), event=Authored(todo='tiledlayout', at=datetime(2026, 11, 23, 5, 1, 0, 846343), actor='bmabsout', kind='todo', created=datetime(2026, 11, 22, 0, 0, 0), body="One general layout for the pages, on a phone and on a desktop from one model: the bar switches workspaces, a workspace is a tree of tiles and every tile is a page; on a wide screen the tree is a partition, on a narrow one the same tree is a stack with the focused tile full screen; opening a page beside another, resizing and going back are acts of one small algebra with laws, and the existing special cases (the list's pane, the secretary's panel) become instances of it.", spec=Flat(value=0.6), rationale=('The pages are already pure programs with addresses, so composing them is', 'cheap, and today each wide layout is written by hand in its page; the', 'owner proposed it.'), category='', waiting_on='', detail="State on 2026-11-22: a design note first, with the case against and a smaller version to compare; no code until the note is accepted.\n\nState on 2026-11-23: the design note is landed (release 2.1.224): one tree with one kind of node, the workspaces as the root's children, the bar as the root's crumb row, a pinned leaf for the secretary; six concepts where today's hand-made layouts have more. Stage a, the general module and its laws wired to nothing, is in work.", source=None, subtodos=(), notes=(), note=''))